def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Fit a geometric-based equation."""
    """Consider only the gate and drain voltage in the equation."""
    return parameters[0] * (gate_voltage_abs**2) * (drain_voltage_abs**2)
